import pytest
from candidate import string_xor


class TestStringXor:
    def test_xor_example_from_docstring(self):
        assert string_xor('010', '110') == '100'

    def test_xor_all_zeros(self):
        assert string_xor('0000', '0000') == '0000'

    def test_xor_all_ones(self):
        assert string_xor('1111', '1111') == '0000'

    def test_xor_complement_strings(self):
        assert string_xor('0101', '1010') == '1111'

    def test_xor_single_bit_same(self):
        assert string_xor('0', '0') == '0'

    def test_xor_single_bit_different(self):
        assert string_xor('0', '1') == '1'

    def test_xor_single_bit_one_and_zero(self):
        assert string_xor('1', '0') == '1'

    def test_xor_single_bit_one_and_one(self):
        assert string_xor('1', '1') == '0'

    def test_xor_empty_strings(self):
        assert string_xor('', '') == ''

    def test_xor_one_empty_one_nonempty(self):
        assert string_xor('', '010') == ''

    def test_xor_nonempty_and_empty(self):
        assert string_xor('010', '') == ''

    def test_xor_different_lengths_shorter_first(self):
        assert string_xor('01', '0101') == '00'

    def test_xor_different_lengths_longer_first(self):
        assert string_xor('0101', '01') == '00'

    def test_xor_long_strings(self):
        a = '0101010101'
        b = '1010101010'
        assert string_xor(a, b) == '1111111111'

    def test_xor_identical_strings_returns_zeros(self):
        s = '11001100'
        assert string_xor(s, s) == '00000000'

    def test_xor_returns_string_type(self):
        result = string_xor('01', '10')
        assert isinstance(result, str)

    def test_xor_none_first_argument(self):
        with pytest.raises(TypeError):
            string_xor(None, '010')

    def test_xor_none_second_argument(self):
        with pytest.raises(TypeError):
            string_xor('010', None)

    def test_xor_none_both_arguments(self):
        with pytest.raises(TypeError):
            string_xor(None, None)

    def test_xor_integer_first_argument(self):
        with pytest.raises(TypeError):
            string_xor(123, '010')

    def test_xor_integer_second_argument(self):
        with pytest.raises(TypeError):
            string_xor('010', 123)

    def test_xor_list_first_argument(self):
        with pytest.raises(TypeError):
            string_xor(['0', '1'], '01')

    def test_xor_list_second_argument(self):
        with pytest.raises(TypeError):
            string_xor('01', ['0', '1'])

    def test_xor_result_length_equals_min_length(self):
        assert len(string_xor('11111', '00')) == 2

    def test_xor_two_character_strings(self):
        assert string_xor('00', '11') == '11'

    def test_xor_three_character_strings(self):
        assert string_xor('111', '000') == '111'

    def test_xor_mixed_bits_normal(self):
        assert string_xor('10010', '11100') == '01110'

    def test_xor_preserves_order(self):
        assert string_xor('0110', '0011') == '0101'
